"""Private video reviews and a small CRM; specialist text is never generated by AI."""

import hashlib
from datetime import datetime
from zoneinfo import ZoneInfo

from flask import g, request

from . import age_months, body, object_get, protected, reason, require
from .commerce import policies
from .db import audit, emit, insert, transaction, uid, unpack, update
from .privacy import consent_required
from .screening import idempotent

STATES = {
    "awaiting_video": "Ожидаем видео",
    "video_received": "Видео получено",
    "in_review": "На просмотре",
    "conclusion_sent": "Заключение отправлено",
    "invited": "Приглашён на диагностику",
    "booked": "Записан",
    "completed": "Диагностика проведена",
    "closed": "Закрыто",
}


def short_text(data, key, maximum=3000, optional=False):
    value = data.get(key, "")
    require(
        isinstance(value, str) and len(value.strip()) <= maximum and (optional or value.strip()),
        "Проверьте текст поля: " + key,
    )
    return value.strip()


def client_review(obj):
    return {
        **obj,
        "data": {
            k: v
            for k, v in obj["data"].items()
            if k
            in (
                "problem",
                "activity",
                "video_id",
                "conclusion",
                "invitation",
                "booking_id",
            )
        },
    }


def register_crm(app):
    @app.post("/api/video-reviews")
    @protected()
    def create_review():
        d = body()
        subject = object_get(g.db, d.get("subject_id"), "subject", g.actor["id"])
        require(
            subject["status"] == "active" and subject["data"]["kind"] == "child",
            "Выберите действующий профиль ребёнка",
        )
        require(
            36 <= age_months(subject["data"]["birth_date"], g.now) <= 131,
            "Этот маршрут предназначен для детей 3–10 лет",
        )
        concern = d.get("concern")
        require(isinstance(concern, dict), "Выберите проблему")
        activity = concern.get("selected_activity")
        require(activity is None or isinstance(activity, dict), "Проверьте задание")
        activity = (
            {
                k: short_text(activity, k, 1500, optional=True)
                for k in ("id", "title", "instructions")
            }
            if activity
            else None
        )
        payload = {
            "problem": short_text(concern, "text", 2000),
            "activity": activity,
            "assigned_to": None,
            "next_contact": None,
            "comments": [],
            "video_id": None,
            "viewed": None,
            "conclusion_draft": "",
            "conclusion": None,
            "invitation": None,
            "booking_id": None,
            "pending_message_id": None,
        }

        def create():
            obj = insert(
                g.db, "video_review", payload, g.now, g.actor["id"], subject["id"], "awaiting_video"
            )
            audit(g.db, g.actor["id"], "crm.create", obj, g.now, "Обращение на просмотр видео")
            return obj

        obj = idempotent(
            g.db,
            "video-review:" + g.actor["id"],
            d.get("key"),
            {**payload, "subject_id": subject["id"]},
            create,
        )
        return client_review(obj), 201

    @app.get("/api/video-reviews/<id>")
    @protected()
    def get_review(id):
        return client_review(object_get(g.db, id, "video_review", g.actor["id"]))

    @app.post("/api/video-reviews/<id>/video")
    @protected()
    def upload_video(id):
        consent_required(g.db, g.actor["id"])
        obj = object_get(g.db, id, "video_review", g.actor["id"])
        policy = policies(g.db, "privacy")
        limit = min(policy["data"].get("media_max_bytes", 0), 20 * 1024 * 1024)
        require(
            limit > 0 and policy["data"].get("retention_days", 0) > 0,
            "Настройте условия хранения видео",
        )
        file = request.files.get("file")
        require(file, "Отправьте видео MP4")
        data = file.read(limit + 1)
        require(0 < len(data) <= limit, "Видео превышает допустимый размер")
        require(data[4:8] == b"ftyp" and file.mimetype == "video/mp4", "Нужно видео MP4")
        digest = hashlib.sha256(data).hexdigest()
        existing = g.db.execute(
            "SELECT id FROM blobs WHERE case_id=? AND digest=?", (id, digest)
        ).fetchone()
        if existing:
            return client_review(obj)
        require(obj["status"] == "awaiting_video", "Видео уже передано специалисту", 409)
        from .media import verify_video

        verify_video(data)
        blob_id = uid()
        # Legacy case_id is the private attachment group, also used for a video review.
        g.db.execute(
            "INSERT INTO blobs VALUES(?,?,?,?,?,?,?,?)",
            (blob_id, obj["owner"], obj["subject"], id, "video/mp4", digest, data, g.now),
        )
        media = insert(
            g.db,
            "media",
            {
                "review_id": id,
                "purpose": "crm_video",
                "mime": "video/mp4",
                "size": len(data),
                "retention_policy_id": policy["id"],
                "expires": g.now + policy["data"]["retention_days"] * 86400,
            },
            g.now,
            obj["owner"],
            obj["subject"],
            "ready",
            id=blob_id,
        )
        result = update(
            g.db,
            obj,
            g.now,
            {
                **obj["data"],
                "video_id": blob_id,
                "client_note": short_text(
                    {"text": request.form.get("note", "")}, "text", optional=True
                ),
            },
            "video_received",
        )
        audit(
            g.db,
            g.actor["id"],
            "crm.video-upload",
            media,
            g.now,
            "Видео для просмотра специалистом",
        )
        audit(
            g.db,
            g.actor["id"],
            "crm.video-received",
            result,
            g.now,
            "Видео получено",
            obj["revision"],
        )
        emit(g.db, obj["owner"], id, "crm.video_received", g.now)
        return client_review(result), 201

    @app.get("/api/admin/crm")
    @protected(admin=True)
    def crm_list():
        status = request.args.get("status") or None
        assigned = request.args.get("assigned_to") or None
        query = "%" + request.args.get("q", "")[:100] + "%"
        rows = g.db.execute(
            "SELECT o.*,a.name AS client_name,a.telegram_id FROM objects o "
            "JOIN accounts a ON a.id=o.owner WHERE o.kind='video_review' "
            "AND (? IS NULL OR o.status=?) AND (? IS NULL OR json_extract(o.data,'$.assigned_to')=?) "
            "AND (a.name LIKE ? OR o.data LIKE ?) ORDER BY o.updated DESC,o.id LIMIT 201",
            (status, status, assigned, assigned, query, query),
        )
        specialists = [
            dict(r)
            for r in g.db.execute("SELECT id,name FROM accounts WHERE role='admin' AND blocked=0")
        ]
        items = [unpack(r) for r in rows]
        return {
            "items": items[:200],
            "states": STATES,
            "specialists": specialists,
            "truncated": len(items) > 200,
        }  # The UI explicitly states the 200-card window.

    @app.get("/api/admin/crm/<id>")
    @protected(admin=True)
    def crm_card(id):
        obj = object_get(g.db, id, "video_review")
        account = dict(
            g.db.execute(
                "SELECT id,name,telegram_id FROM accounts WHERE id=?", (obj["owner"],)
            ).fetchone()
        )
        return {
            "object": obj,
            "specialists": [
                dict(r)
                for r in g.db.execute(
                    "SELECT id,name FROM accounts WHERE role='admin' AND blocked=0"
                )
            ],
            "delivery": dict(row)
            if (
                row := g.db.execute(
                    "SELECT id,status,attempts FROM outbox WHERE object_id=? ORDER BY created DESC LIMIT 1",
                    (obj["data"].get("pending_message_id"),),
                ).fetchone()
            )
            else None,
            "account": account,
            "subject": object_get(g.db, obj["subject"], "subject"),
            "states": STATES,
            "audit": [
                dict(r)
                for r in g.db.execute("SELECT * FROM audit WHERE object_id=? ORDER BY id", (id,))
            ],
        }

    @app.post("/api/admin/crm/<id>/<action>")
    @protected(admin=True)
    def crm_action(id, action):
        obj = object_get(g.db, id, "video_review")
        d = body()
        why = reason(d)
        require(d.get("revision") == obj["revision"], "Карточка изменена, обновите её", 409)
        payload, state = {**obj["data"]}, obj["status"]
        require(
            action
            in (
                "assign",
                "comment",
                "next-contact",
                "take",
                "viewed",
                "conclusion",
                "send-conclusion",
                "invite",
                "close",
            ),
            "Неизвестное действие",
            404,
        )
        if action == "assign":
            actor = g.db.execute(
                "SELECT * FROM accounts WHERE id=? AND role='admin' AND blocked=0",
                (d.get("assigned_to"),),
            ).fetchone()
            require(actor, "Выберите действующего специалиста")
            payload["assigned_to"] = actor["id"]
        elif action == "comment":
            payload["comments"] = [
                *payload["comments"],
                {"text": short_text(d, "text"), "actor": g.actor["id"], "at": g.now},
            ]
        elif action == "next-contact":
            value = d.get("next_contact")
            require(
                value is None or type(value) is int and value > g.now,
                "Укажите будущую дату контакта",
            )
            payload["next_contact"] = value
        elif action in ("take", "viewed"):
            require(
                state in ("video_received", "in_review") and payload["video_id"],
                "Нет видео для просмотра",
                409,
            )
            payload["assigned_to"] = payload["assigned_to"] or g.actor["id"]
            state = "in_review"
            if action == "viewed":
                payload["viewed"] = {
                    "actor": g.actor["id"],
                    "at": g.now,
                    "video_id": payload["video_id"],
                }
        elif action == "conclusion":
            require(
                state == "in_review" and not payload["pending_message_id"],
                "Ответ уже отправляется или карточка закрыта",
                409,
            )
            payload["conclusion_draft"] = short_text(d, "text")
        elif action in ("send-conclusion", "invite"):
            require(not payload["pending_message_id"], "Сообщение уже отправляется", 409)
            if action == "send-conclusion":
                require(
                    state == "in_review" and payload["viewed"] and payload["conclusion_draft"],
                    "Подтвердите просмотр видео и сохраните мини-заключение",
                )
                text, message_type = payload["conclusion_draft"], "conclusion"
            else:
                require(state == "conclusion_sent", "Сначала отправьте мини-заключение", 409)
                text, message_type = short_text(d, "text"), "invitation"
            msg = insert(
                g.db,
                "crm_message",
                {
                    "review_id": id,
                    "text": text,
                    "message_type": message_type,
                    "actor": g.actor["id"],
                },
                g.now,
                obj["owner"],
                obj["subject"],
                "queued",
            )
            payload["pending_message_id"] = msg["id"]
            emit(g.db, obj["owner"], msg["id"], "crm.message", g.now)
        elif action == "close":
            require(
                not payload["pending_message_id"] and state not in ("booked", "completed"),
                "Сначала завершите доставку или отмените подтверждённую запись",
                409,
            )
            if payload.get("booking_id"):
                booking = object_get(g.db, payload["booking_id"], "booking")
                require(
                    booking["status"] == "cancelled", "Сначала отмените заявку на диагностику", 409
                )
            state = "closed"
            payload["next_contact"] = None
        result = update(g.db, obj, g.now, payload, state)
        audit(g.db, g.actor["id"], "crm." + action, result, g.now, why, obj["revision"])
        return result

    @app.post("/api/video-reviews/<id>/book")
    @protected()
    def request_diagnostic(id):
        obj = object_get(g.db, id, "video_review", g.actor["id"])
        require(
            obj["status"] in ("invited", "booked"),
            "Приглашение на диагностику ещё не отправлено",
            409,
        )
        if obj["data"].get("booking_id"):
            old = object_get(g.db, obj["data"]["booking_id"], "booking", obj["owner"])
            if old["status"] != "cancelled":
                return old
        d = body()
        booking = insert(
            g.db,
            "booking",
            {
                "topic": "Полная диагностика: " + obj["data"]["problem"],
                "preferences": short_text(d, "preferences"),
                "proposals": [],
                "current_proposal": None,
                "review_id": id,
            },
            g.now,
            obj["owner"],
            obj["subject"],
            "requested",
        )
        result = update(g.db, obj, g.now, {**obj["data"], "booking_id": booking["id"]})
        audit(
            g.db,
            g.actor["id"],
            "crm.booking-requested",
            result,
            g.now,
            "Клиент запросил запись на полную диагностику",
            obj["revision"],
        )
        emit(g.db, obj["owner"], booking["id"], "booking.requested", g.now)
        return booking, 201


def sync_booking(db, booking, now, actor, why):
    review_id = booking["data"].get("review_id")
    if not review_id:
        return
    obj = object_get(db, review_id, "video_review", booking["owner"])
    if obj["data"].get("booking_id") != booking["id"]:
        return
    state = {"confirmed": "booked", "completed": "completed"}.get(booking["status"])
    if state is None and obj["status"] == "booked":
        state = "invited"
    if state and state != obj["status"]:
        payload = {**obj["data"]}
        if state == "completed":
            payload["next_contact"] = None
        result = update(db, obj, now, payload, state)
        audit(db, actor, "crm.booking-" + booking["status"], result, now, why, obj["revision"])


def message_delivery(db, event, now, delivered):
    msg = object_get(db, event["object_id"], "crm_message")
    if not delivered or msg["status"] == "sent":
        return
    obj = object_get(db, msg["data"]["review_id"], "video_review")
    kind = msg["data"]["message_type"]
    result = update(
        db,
        obj,
        now,
        {**obj["data"], kind: msg["data"]["text"], "pending_message_id": None},
        "conclusion_sent" if kind == "conclusion" else "invited",
    )
    update(db, msg, now, status="sent")
    audit(
        db,
        msg["data"]["actor"],
        "crm." + kind + "-delivered",
        result,
        now,
        "Telegram подтвердил отправку сообщения",
        obj["revision"],
    )


def notify_crm(app, owner, object_id, event):
    """Freeze the sent text; callbacks are owned by the recipient, never the specialist."""
    from .providers import telegram

    with transaction(app.config["DATABASE"]) as db:
        account = db.execute("SELECT telegram_id FROM accounts WHERE id=?", (owner,)).fetchone()
        require(account, "Клиент не найден")
        buttons = []
        if event == "crm.message":
            msg = object_get(db, object_id, "crm_message", owner)
            if msg["status"] == "sent":
                return
            text = msg["data"]["text"]
            if msg["data"]["message_type"] == "invitation":
                buttons = [
                    ("Записаться на диагностику", "crm_booking", {"id": msg["data"]["review_id"]})
                ]
        else:
            booking = object_get(db, object_id, "booking", owner)
            if (event == "booking.propose" and booking["status"] != "proposed") or (
                event in ("booking.connection", "booking.confirm")
                and booking["status"] != "confirmed"
            ):
                return
            if event == "booking.propose":
                proposal = next(
                    p
                    for p in booking["data"]["proposals"]
                    if p["id"] == booking["data"]["current_proposal"]
                )
                stamp = datetime.fromtimestamp(
                    proposal["starts"], ZoneInfo(proposal["timezone"])
                ).strftime("%d.%m.%Y %H:%M")
                text = f"Полная диагностика: {stamp} ({proposal['timezone']}), {proposal['duration_minutes']} минут. Подтвердите время."
                buttons = [
                    (
                        "Подтвердить время",
                        "booking_confirm",
                        {"id": object_id, "proposal_id": proposal["id"]},
                    ),
                    ("Предложить другое время", "crm_reschedule", {"id": object_id}),
                ]
            elif event == "booking.connection":
                text = "Ссылка на полную диагностику: " + str(
                    booking["data"].get("connection") or ""
                )
            else:
                text = {
                    "booking.complete": "Специалист отметил диагностику проведённой.",
                    "booking.cancel": "Запись на диагностику отменена.",
                    "booking.confirm": "Время полной диагностики подтверждено.",
                    "booking.reschedule": "Запрос на другое время передан специалисту.",
                }.get(event, "Обновилась запись на диагностику.")
        markup = []
        for title, action, data in buttons:
            callback = insert(
                db,
                "bot_callback",
                {"action": action, **data},
                int(app.config["CLOCK"]()),
                owner,
                status="active",
            )
            markup.append([{"text": title, "callback_data": "b:" + callback["id"]}])
    payload = {"chat_id": account["telegram_id"], "text": text}
    if markup:
        payload["reply_markup"] = {"inline_keyboard": markup}
    telegram(app, "sendMessage", payload)
